package state

import (
	"context"
	"errors"
	"strings"

	appvault "github.com/mslxl/natcatty/application/vault"
	"github.com/mslxl/natcatty/domain/model"
)

// Exports is the Vault export use-case seam. The application Service
// implements it; tests provide a fake.
type Exports interface {
	ExportVault(ctx context.Context, opts appvault.ExportOptions) (appvault.Export, error)
}

// ExportWriter saves generated bytes through the native save dialog. It is
// called on the UI thread and returns path "", nil when the user cancels.
type ExportWriter interface {
	Save(name string, content []byte) (path string, err error)
}

// WithExports gives the Vault surface export use cases.
func WithExports(exports Exports) Option {
	return func(s *State) { s.exports = exports }
}

// WithExportWriter gives the Vault surface the native save dialog. Without it
// exporting reports ProblemExportWriter.
func WithExportWriter(writer ExportWriter) Option {
	return func(s *State) { s.exportWriter = writer }
}

// Export scope codes.
const (
	ExportScopeAll      = "all"
	ExportScopeSelected = "selected"
)

// ExportOutcome is the last saved export, shown as a dismissible banner. It
// carries the destination and counts only, never credential material.
type ExportOutcome struct {
	Path       string
	Bytes      int
	Unreadable int
	// Omitted counts stored credentials left out because IncludeSecrets was
	// off. The banner names the count so an incomplete file is never silent.
	Omitted int
}

// ExportOpen reports whether the export panel is showing.
func (s *State) ExportOpen() bool { return s.exportActive }

// ExportFormatValue returns the selected format, or JSON before a choice.
func (s *State) ExportFormatValue() string {
	if s.exportFormat == "" {
		return string(appvault.ExportJSON)
	}
	return s.exportFormat
}

// SetExportFormat changes the output format.
func (s *State) SetExportFormat(format string) bool {
	format = strings.TrimSpace(format)
	if format == s.exportFormat || !appvault.ExportFormat(format).Valid() {
		return false
	}
	s.exportFormat = format
	s.exportProblem = ProblemNone
	s.redraw()
	return true
}

// ExportScopeValue returns the selected scope code.
func (s *State) ExportScopeValue() string {
	if s.exportScope == "" {
		return ExportScopeAll
	}
	return s.exportScope
}

// SetExportScope restricts the export to one Host or the whole Vault.
func (s *State) SetExportScope(scope string) bool {
	if scope != ExportScopeSelected {
		scope = ExportScopeAll
	}
	if scope == s.exportScope {
		return false
	}
	s.exportScope = scope
	s.exportProblem = ProblemNone
	s.redraw()
	return true
}

// ExportIncludesSecrets reports whether plaintext credentials are selected.
func (s *State) ExportIncludesSecrets() bool { return s.exportSecrets }

// ExportSecretsConfirmed reports whether the plaintext warning was confirmed.
func (s *State) ExportSecretsConfirmed() bool { return s.exportConfirmed }

// SetExportIncludeSecrets toggles plaintext credentials. Turning it on always
// requires a fresh confirmation, so a previously confirmed export cannot leak
// secrets again without the user seeing the warning.
func (s *State) SetExportIncludeSecrets(include bool) {
	s.exportSecrets = include
	s.exportConfirmed = false
	s.exportProblem = ProblemNone
	s.redraw()
}

// ConfirmExportSecrets accepts the plaintext warning.
func (s *State) ConfirmExportSecrets() {
	if !s.exportSecrets {
		return
	}
	s.exportConfirmed = true
	s.exportProblem = ProblemNone
	s.redraw()
}

// ExportProblem reports a failure the panel must localize.
func (s *State) ExportProblem() Problem { return s.exportProblem }

// BeginExport closes every editor and opens the export panel. No dialog or
// file is touched until Export is pressed.
func (s *State) BeginExport() {
	s.closeEditors()
	s.exportActive = true
	s.exportFormat = string(appvault.ExportJSON)
	s.exportScope = ExportScopeAll
	if s.selected == "" {
		s.exportScope = ExportScopeAll
	} else {
		s.exportScope = ExportScopeSelected
	}
	s.exportSecrets = false
	s.exportConfirmed = false
	s.exportProblem = ProblemNone
	s.redraw()
}

// CancelExport closes the panel. An earlier outcome banner is left for the
// list.
func (s *State) CancelExport() {
	s.closeExport()
	s.redraw()
}

// Export renders the selection and saves it through the native dialog. The
// panel stays open when the dialog is cancelled or the write fails; secrets
// cannot be exported until their warning is confirmed.
func (s *State) Export(title string) error {
	if !s.exportActive {
		return nil
	}
	if s.exports == nil || s.exportWriter == nil {
		s.exportProblem = ProblemExportUnavailable
		s.redraw()
		return nil
	}
	if s.exportSecrets && !s.exportConfirmed {
		s.exportProblem = ProblemExportUnconfirmed
		s.redraw()
		return nil
	}
	format := appvault.ExportFormat(s.ExportFormatValue())
	if !format.Valid() {
		s.exportProblem = ProblemExportFormat
		s.redraw()
		return nil
	}
	opts := appvault.ExportOptions{
		Format:         format,
		Title:          title,
		IncludeSecrets: s.exportSecrets,
	}
	if s.ExportScopeValue() == ExportScopeSelected {
		if s.selected == "" {
			s.exportProblem = ProblemExportNoHost
			s.redraw()
			return nil
		}
		opts.HostIDs = []model.HostID{s.selected}
	}
	export, err := s.exports.ExportVault(context.Background(), opts)
	if err != nil {
		s.exportProblem = exportProblemFor(err)
		s.redraw()
		return err
	}
	path, err := s.exportWriter.Save(export.Filename, export.Content)
	if err != nil {
		s.exportProblem = ProblemExportWriter
		s.redraw()
		return err
	}
	if path == "" {
		// The user cancelled the save dialog; keep the chosen options.
		s.exportProblem = ProblemNone
		s.redraw()
		return nil
	}
	s.exportOutcome = &ExportOutcome{
		Path: path, Bytes: len(export.Content), Unreadable: export.UnreadableSecrets,
		Omitted: export.OmittedSecrets,
	}
	s.closeExport()
	s.redraw()
	return nil
}

// ExportOutcome returns the last saved export for the list banner.
func (s *State) ExportOutcome() (ExportOutcome, bool) {
	if s.exportOutcome == nil {
		return ExportOutcome{}, false
	}
	return *s.exportOutcome, true
}

// DismissExportOutcome hides the export summary banner.
func (s *State) DismissExportOutcome() {
	s.exportOutcome = nil
	s.redraw()
}

func (s *State) closeExport() {
	s.exportActive = false
	s.exportProblem = ProblemNone
}

func exportProblemFor(err error) Problem {
	var typed *appvault.Error
	if errors.As(err, &typed) && typed.Kind == appvault.KindValidation {
		return ProblemExportFormat
	}
	return problemFor(err)
}
